    artist_sources_gmail = defaultdict(list)
    email_query='Recommendations for Music Artists'
    page_limit=20
    thread_ids_all=[]
    page_index=0
    while True:
        res=apis.gmail.show_outbox_threads(access_token=gmail_token, query=email_query, page_index=page_index, page_limit=page_limit)
        print('gmail outbox page',page_index,'len',len(res))
        if not res:
            break
        thread_ids_all += [t['email_thread_id'] for t in res]
        page_index += 1
    pattern = re.compile(r'favorites\s+artists\s*[,:]?\s*(.*)', re.IGNORECASE|re.DOTALL)
    for tid in thread_ids_all:
        th=apis.gmail.show_thread(access_token=gmail_token, email_thread_id=tid)
        for e in th['emails']:
            sender_email=e['sender']['email']
            if sender_email.lower()==mir_email.lower():
                continue
            body=e.get('body','')
            m=pattern.search(body)
            if not m:
                continue
            rest=m.group(1).strip()
            rest=re.sub(r'\s+',' ',rest)
            rest=re.split(r'(?:\bThanks\b|\bThank\b|\bHere\b|\bSure\b|\bAwesome\b)', rest, flags=re.IGNORECASE)[0].strip()
            parts=[p.strip() for p in rest.split(',') if p.strip()]
            final_parts=[]
            for p in parts:
                if ' and ' in p:
                    final_parts += [x.strip() for x in p.split(' and ') if x.strip()]
                else:
                    final_parts.append(p)
            names=[x for x in final_parts if re.search(r'[A-Za-z]', x)]
            names=[re.sub(r'^[\-–\s]+|[\-–\s]+$', '', x) for x in names]
            for name in names:
                artist_sources_gmail[name].append({'thread_id':tid,'from_name':e['sender']['name'],'from_email':sender_email,'email_id':e['email_id']})

if 'artist_sources_phone' not in globals():
    msgs=[]
    queries=['favorites artists','favorite artists','favorite artist']
    for q in queries:
        page_index=0
        page_limit=20
        while True:
            res=apis.phone.search_text_messages(access_token=phone_token, query=q, page_index=page_index, page_limit=page_limit)
            if not res:
                break
            msgs += res
            page_index += 1

    def extract_names(text):
        if not re.search(r"favorites?\s+artists", text, flags=re.IGNORECASE):
            return []
        m=re.search(r"favorites?\s+artists\s*,?\s*(.*)", text, flags=re.IGNORECASE|re.DOTALL)
        if not m:
            return []
        rest=m.group(1).strip()
        rest=re.split(r"\b(favorite songs|songs)\b", rest, flags=re.IGNORECASE)[0]
        rest=rest.strip(' .!?:;\n\t')
        if not rest:
            return []
        parts=[p.strip() for p in rest.split(',') if p.strip()]
        final=[]
        for p in parts:
            if re.search(r"\band\b", p, flags=re.IGNORECASE):
                subs=[s.strip() for s in re.split(r"\band\b", p, flags=re.IGNORECASE) if s.strip()]
                final.extend(subs)
            else:
                final.append(p)
        cleaned=[]
        for x in final:
            x=re.sub(r"^[\"'\-–\s]+|[\"'\-–\s]+$", '', x)
            if re.search(r'[A-Za-z]', x):
                cleaned.append(x)
        return cleaned

    artist_sources_phone=defaultdict(list)
    for m in msgs:
        sender_phone=m['sender'].get('phone_number')
        if sender_phone==mir_phone:
            continue
        text=m.get('message','')
        names=extract_names(text)
        for nm in names:
            artist_sources_phone[nm].append({'text_message_id':m['text_message_id'],'sender_name':m['sender']['name'],'sender_phone':sender_phone})

# Determine unique senders from both sources
email_senders=set()
for artist, srcs in artist_sources_gmail.items():
    for s in srcs:
        email_senders.add((s['from_name'], s['from_email']))

phone_senders=set()
for artist, srcs in artist_sources_phone.items():
    for s in srcs:
        phone_senders.add((s['sender_name'], s['sender_phone']))

print('email_senders',sorted(email_senders))
print('phone_senders',sorted(phone_senders))

# Resolve these identities through phone contacts
resolved_email=set()  # set of from_email
resolved_phone=set()  # set of sender_phone

resolved_contacts=[]

for full_name,email in email_senders:
    parts=full_name.split(' ',1)
    first=parts[0]
    last=parts[1] if len(parts)>1 else None
    c=resolve_contact(first, last_name=last, email=email)
    resolved_contacts.append((full_name,email,c.get('phone_number') if c else None))
    if c:
        resolved_email.add(email.lower())

for full_name,phone in phone_senders:
    parts=full_name.split(' ',1)
    first=parts[0]
    last=parts[1] if len(parts)>1 else None
    c=resolve_contact(first, last_name=last, phone_number=phone)
    resolved_contacts.append((full_name,phone,c.get('email') if c else None))
    if c:
        resolved_phone.add(phone)

print('resolved_email',resolved_email)
print('resolved_phone',resolved_phone)
print('resolved_contacts_samples',resolved_contacts[:10])

# Build target artist set based on resolved sender identities only

target_info=[]  # list of dict {artist_name, source_type, sender}

for artist, srcs in artist_sources_gmail.items():
    for s in srcs:
        if s['from_email'].lower() in resolved_email:
            target_info.append({'artist_name':artist,'source':'coworker_email','sender':s['from_name'],'sender_email':s['from_email']})
            break

for artist, srcs in artist_sources_phone.items():
    for s in srcs:
        if s['sender_phone'] in resolved_phone:
            target_info.append({'artist_name':artist,'source':'friend_phone','sender':s['sender_name'],'sender_phone':s['sender_phone']})
            break

# Deduplicate by artist_name keeping first record
seen=set(); target_dedup=[]
for item in target_info:
    if item['artist_name'].strip().lower() in seen:
        continue
    seen.add(item['artist_name'].strip().lower())
    target_dedup.append(item)

print('target artist names after identity resolution',len(target_dedup))
for it in sorted(target_dedup, key=lambda x:x['artist_name']):
    print(it)

# Map artists to spotify ids
artist_names=[it['artist_name'] for it in target_dedup]

# Fetch current following artists (paginate fully)
following=[]
page_index=0
page_limit=20
while True:
    res=apis.spotify.show_following_artists(access_token=spotify_token, page_index=page_index, page_limit=page_limit)
    print('spotify following page',page_index,'len',len(res))
    if not res:
