# search artists and build mapping with exact match
def find_exact_artist_id(name):
    all_res=[]
    page_index=0
    page_limit=20
    while True:
        res=apis.spotify.search_artists(query=name, page_index=page_index, page_limit=page_limit)
        print('search_artists',name,'page',page_index,'len',len(res))
        if not res:
            break
        all_res += res
        page_index += 1
    exact=[r for r in all_res if r.get('name','').strip().lower()==name.strip().lower()]
    if len(exact)==1:
        return exact[0]['artist_id']
    if len(exact)>1:
        print('AMBIGUOUS spotify exact matches for',name,'count',len(exact),'EXCLUDE')
        return None
    print('No exact spotify match for',name)
    return None

name_to_id={}
missing=[]
for name in artist_names:
    aid=find_exact_artist_id(name)
    if aid is None:
        missing.append(name)
    else:
        name_to_id[name]=aid

print('missing spotify matches',missing)

# Build delta list excluding already-following
need=[(n, name_to_id[n]) for n in name_to_id if name_to_id[n] not in following_ids]
print('Need follow count',len(need))
print('Need follow list',sorted(need, key=lambda x:x[0]))

# Prepare verification table for follow action
for n,aid in sorted(need, key=lambda x:x[0]):
    src=[it for it in target_dedup if it['artist_name']==n]
    print('VERIFY',n,'artist_id',aid,'source',src[0]['source'],'sender',src[0].get('sender') if src else None)

